Here is the commit message:
mtd: parsers: Fix memory leak in
 mtd_parser_tplink_safeloader_parse()

The function mtd_parser_tplink_safeloader_parse() allocates buf via
mtd_parser_tplink_safeloader_read_table(). If the allocation for
parts[idx].name fails inside the loop, the code jumps to the err_free
label without freeing buf, leading to a memory leak.

Fix this by freeing the temporary buffer buf in the err_free label.

Compile tested only. Issue found using a prototype static analysis tool
and code review.

Fixes: 00a3588084be ("mtd: parsers: add TP-Link SafeLoader partitions table parser")
Signed-off-by: Zilin Guan <zilin@seu.edu.cn>
Signed-off-by: Miquel Raynal <miquel.raynal@bootlin.com>

Here is the root cause:
In `mtd_parser_tplink_safeloader_parse()`, the temporary buffer `buf` is allocated via `mtd_parser_tplink_safeloader_read_table()`. Inside the loop that allocates partition names (`parts[idx].name`), if `kstrdup()` fails, the code jumps to the `err_free` label, which only frees previously allocated partition names and the parts array but does not free `buf`, causing a memory leak.

Here is the patch:

 static int mtd_parser_tplink_safeloader_parse(struct mtd_info *mtd,
 					      const struct mtd_partition **pparts,
 					      struct mtd_part_parser_data *data)
 {
 	struct mtd_partition *parts;
 	char name[65];
 	size_t offset;
 	size_t bytes;
 	char *buf;
 	int idx;
 	int err;

 	parts = kcalloc(TPLINK_SAFELOADER_MAX_PARTS, sizeof(*parts), GFP_KERNEL);
 	if (!parts) {
 		err = -ENOMEM;
 		goto err_out;
 	}

 	buf = mtd_parser_tplink_safeloader_read_table(mtd);
 	if (!buf) {
 		err = -ENOENT;
 		goto err_free_parts;
 	}

 	for (idx = 0, offset = TPLINK_SAFELOADER_DATA_OFFSET;
 	     idx < TPLINK_SAFELOADER_MAX_PARTS &&
 	     sscanf(buf + offset, "partition %64s base 0x%llx size 0x%llx%zn\n",
 		    name, &parts[idx].offset, &parts[idx].size, &bytes) == 3;
 	     idx++, offset += bytes + 1) {
 		parts[idx].name = kstrdup(name, GFP_KERNEL);
 		if (!parts[idx].name) {
 			err = -ENOMEM;
 			goto err_free;
 		}
 	}

 	if (idx == TPLINK_SAFELOADER_MAX_PARTS)
 		pr_warn("Reached maximum number of partitions!\n");

 	kfree(buf);

 	*pparts = parts;

 	return idx;

 err_free:
+	kfree(buf);
 	for (idx -= 1; idx >= 0; idx--)
 		kfree(parts[idx].name);
 err_free_parts:
 	kfree(parts);
 err_out:
 	return err;
 };



